        "tex": "\\oint\\mathbf H\\cdot d\\mathbf l=NI",
        "plain": "閉合路徑 H 線積分=所包圍安匝",
        "why": "假設磁準靜態且積分參考方向與繞組電流一致。 此式尚未包含真實硬體寄生與材料非線性。"
