  "14": {
    "lesson": "bh",
    "title": "B-H 曲線變平時，為何電感電流可能急速上升？",
    "question": "磁芯接近飽和，增量導磁率與電感的變化代表什麼？",
    "takeaway": "B-H 局部斜率 μinc 變小會降低增量電感，固定外加電壓的電流斜率可能顯著增加。",
    "intuition": [
      "H 是磁化強度、B 是磁通密度。線性區增加 H，B 也顯著增加；接近飽和時 H 大增而 B 只增加少量。",
      "對固定匝數、截面與磁路長度，電感是磁通鏈結隨電流改變的斜率。若增量電感下降，電壓相同時 di/dt 會上升。"
    ],
    "steps": [
      {
        "title": "先對照原圖的線性區與飽和區",
        "detail": "B 軸的單位為 T，H 軸為 A/m；曲線變平意味局部 ΔB/ΔH 變小，不是磁芯停止有電流。"
      },
      {
        "title": "區分弦導磁率與增量導磁率",
        "detail": "B/H 是由原點到工作點的比例，ΔB/ΔH 是工作點附近的局部斜率，兩者在非線性區不同。"
      },
      {
        "title": "將局部導磁率換算到電感",
        "detail": "固定磁路幾何時 Linc≈N²A μinc/ℓ，局部 μinc 減小會使相同電壓下電流上升更快。"
      },
      {
        "title": "連結到波形觀察與安全",
        "detail": "示波器若看到電感電流斜率突然增加，應排查磁芯飽和、溫度與伏秒，而不是把高斜率視為正常 PWM 響應。"
      }
    ],
    "equations": [
      {
        "label": "增量導磁率",
        "tex": "\\mu_{\\rm inc}\\approx\\frac{\\Delta B}{\\Delta H}",
        "plain": "μinc≈ΔB/ΔH（H/m）",
        "why": "需取工作點附近的斜率，忽略動態磁滯影響。 此式尚未包含真實硬體寄生與材料非線性。"
      },
      {
        "label": "固定幾何增量電感",
        "tex": "L_{\\rm inc}\\approx\\frac{N^2A}{\\ell}\\mu_{\\rm inc}",
        "plain": "Linc≈N²A μinc/ℓ",
        "why": "採均勻線性化磁路、固定幾何與忽略漏磁的近似。 此式尚未包含真實硬體寄生與材料非線性。"
      },
      {
        "label": "電壓與電流斜率",
        "tex": "\\frac{di}{dt}\\approx\\frac{v}{L_{\\rm inc}}",
        "plain": "di/dt≈v/Linc",
        "why": "忽略繞組電阻；使用局部增量 L，而非飽和前的標稱 L。"
      }
    ],
    "worked": {
      "given": "另設 B-H 示意點：線性區 H=100→200 A/m、B=0.20→0.30 T；較平區 H=800→1000 A/m、B=0.80→0.85 T。",
      "steps": [
        "線性區局部平均 μinc≈(0.30−0.20)/(200−100)=0.001 H/m。",
        "較平區 μinc≈(0.85−0.80)/(1000−800)=0.00025 H/m，為前者四分之一。",
        "固定相同幾何時增量電感相應降為四分之一；相同端電壓下 di/dt 可能增加四倍。"
      ],
      "result": "示意點不是原講義曲線上的材料數據；真正工作點必須使用磁材資料與溫度、偏磁條件。"
    },
    "assumptions": [
      "以兩段局部線性 B-H 示意點說明增量斜率，並非任何材料的通用飽和門檻。",
      "計算忽略磁滯、渦流、氣隙與線圈損耗；實機須用磁芯規格與電流波形驗證。"
    ],
    "pitfall": "認為磁飽和會限制電流上升；實際常因增量電感下降而更快過流。",
    "check": {
      "q": "增量電感從 100 µH 降至 25 µH、外加電壓不變時，di/dt 如何改變？",
      "a": "在 v=Linc di/dt 近似下，電流斜率變成四倍。"
    },
    "tryIt": "對照 P.14 的 B-H 圖在不同 H 畫切線，觀察 μinc 與電流斜率的對應。"
  },
