        "tex": "E_{\\rm hyst}=w_{\\rm hyst}V_e",
        "plain": "每次磁化循環損失=能量密度×有效磁芯體積",
        "why": "假設工作區間的損失密度可以代表整顆磁芯。 實際損耗與工作點須另外量測確認。"
