        "若改為真實 MOSFET RDS(on)=40 mΩ，10 A 時 ON 壓降約 0.4 V、ON 功率 4 W。",
        "加入有限 dv/dt 與 di/dt 後，換流區可能有額外能量重疊；不能用上述理想 0 W 證明硬體安全。"
