        "在低 VDS 且充分增強近似下，ID≈0.1/0.04=2.5 A、瞬時耗散約 0.25 W。",
        "若 VDS 增至 5 V (>2 V)，不可繼續拿固定 40 mΩ 推算 125 A；這已落在主動區的示意條件。"
