      {
        "title": "在關斷波形追尾電流重疊",
        "detail": "Gate 已撤除後 C–E 電壓可能升高，殘留電流仍在流動，此時 vCE(t)iC(t) 積分形成 Eoff。"
      },
      {
        "title": "由頻率與熱限反推工作範圍",
        "detail": "把實測或資料表 Eon/Eoff 乘實際事件頻率，再加導通損估散熱；頻率上限取決於器件世代與具體工作點。"
      }
