        "tex": "V_{rating}>V_{bus,max}+V_{overshoot}",
        "plain": "額定阻斷電壓需大於最大 Bus 加預估尖峰",
        "why": "這只是初步必要條件，非等同已完成降額、振鈴與異常 SOA 安全驗證。"
