        "tex": "P_{sw}\\approx(E_{on}+E_{off})f_s",
        "plain": "平均切換損≈每次 ON/OFF 總能量×切換頻率",
        "why": "須核對器件測試工況與每秒切換事件數，ZVS／ZCS 可能改變能量分布。"
