    "question": "原圖把四顆二極體上下展開，為何正半週 D1／D2 通，負半週 D3／D4 通？",
    "takeaway": "正半週由 D1 與 D2 串聯供電，負半週由 D3 與 D4 串聯供電；不論 AC 電流方向如何切換，直流端 P 始終為正、N 始終為負。",
