  "75": {
    "lesson": "capacitor",
    "title": "固定 DC 電壓整流器的 THD、DPF、PF：為何輕載相位看起來更好，真 PF 卻可能下降？",
    "question": "原圖隨 Id 下降 THD 上升、DPF 升高，但 PF 反而降低，三條曲線為什麼能同時成立？",
    "takeaway": "DPF 只描述來源電壓基波與電流基波相角；短促充電脈衝推高其他電流諧波的 RMS，因此純正弦電壓下 PF=DPF/√(1+THDi²) 仍可下降。",
    "intuition": [
      "P.75 原圖對應 P.73 固定 Vd、來源 Ls 的脈衝充電電流模型。當負載變輕、DC 電壓更靠近交流峰值，電流會集中在較短導通區段，總諧波 RMS 相對基波可能更大。",
      "同時，基波電流相位可能更接近來源正弦，位移因數 DPF 向 1 靠近；但真 PF 包含基波占總 RMS 的比例。THD 增大時，這個比例減小，可能蓋過 DPF 的改善。"
    ],
    "steps": [
      {
        "title": "先從整流脈衝建立交流電流波形",
        "detail": "在正半週輸入電流為 i(θ)，負半週依二極體橋切換反向為 −i(θ−π)；因此這個理想模型具有半波反對稱，沒有 DC 分量。"
      },
      {
        "title": "由傅立葉係數求基波相角與 RMS",
        "detail": "對完整週期投影到 sin/cos 得 a1、b1，基波 RMS=√(a1²+b1²)/√2；與純正弦來源電壓的相位差決定 DPF。"
      },
      {
        "title": "用總 RMS 與基波計算 THDi",
        "detail": "將整週 i_s(t)² 積分得到 Irms²，扣除基波 RMS² 後剩下諧波平方和，故 THDi=√(Irms²−I1²)/I1。"
      },
      {
        "title": "合成真正 PF 並檢查假設",
        "detail": "在純正弦來源電壓下，平均實功只取同頻基波的相位投影，因此 PF=DPF×I1/Irms；非正弦電壓需重新計算各次同頻功率。"
      }
    ],
    "equations": [
      {
        "label": "電流 THD",
        "tex": "THD_i=\\frac{\\sqrt{I_{rms}^2-I_{1,rms}^2}}{I_{1,rms}}",
        "plain": "THDi=√(總 RMS²−基波 RMS²)/基波 RMS",
        "why": "忽略 DC 與非整數次頻率，且由同一完整週期的電流傅立葉分解得到。"
      },
      {
        "label": "位移功率因數",
        "tex": "DPF=\\cos\\phi_1",
        "plain": "DPF=來源電壓基波與電流基波的相位差餘弦",
        "why": "只看基波相角，不代表諧波電流已消失；若基波電流趨近 0，量測不確定性會增加。"
      },
      {
        "label": "純正弦源下真 PF",
        "tex": "PF=\\frac{DPF}{\\sqrt{1+THD_i^2}}",
        "plain": "純正弦電壓下 PF=DPF/√(1+THDi²)",
        "why": "需電壓純正弦、電流無 DC/非諧波成分並使用完整電流 RMS；不適用任意畸變電網。"
      }
    ],
    "worked": {
      "given": "沿用 Vs=100 Vrms、f=50 Hz、Ls=10 mH 與固定 DC Vd 的理想模型，比較 Vd=0.90Vm 與 0.95Vm。",
      "steps": [
        "Vd=0.90Vm 時整週線電流 Irms≈1.1704 A、基波 I1≈0.89685 A；THDi≈83.85%。",
        "這組波形的基波位移因數 DPF≈0.9341，故真 PF≈0.9341/√(1+0.8385²)≈0.7158。",
        "Vd=0.95Vm 時平均電流更小，模型給 THDi≈115.65%、DPF≈0.9675、真 PF≈0.6328。",
        "兩個工作點中 DPF 反而變大，但真 PF 下降，原因是總線電流波形愈尖，諧波佔比增加。"
      ],
      "result": "這些數字以理想源感和固定 DC 電壓模型計算，不是原始 P.75 圖表上任意可直接讀取的實測點。"
    },
    "assumptions": [
      "以相同理想波形投影計算 THDi、DPF、PF，來源電壓為完整純正弦；零負載時電流趨近零，不能盲目定義其 THD 或 PF。",
      "有來源電阻、電容充放電、二極體 VF、PFC 控制或電網電壓失真時，電流波形與上述解析關係的前提會不同。"
    ],
    "pitfall": "認為 DPF 接近 1 就代表真 PF 也接近 1，或將高 THD 直接視為一定損失多少瓦。",
    "check": {
      "q": "輕載時 DPF 從 0.934 升到 0.968，THDi 卻從 84% 增到 116%，真 PF 一定改善嗎？",
      "a": "不一定，本模型反而從約 0.716 降到 0.633；需同時考慮基波相角和失真 RMS。"
    },
    "tryIt": "在 P.75 原圖把 THD、DPF、PF 三條線分開讀，再用既有 THD/PF 課節驗證純正弦來源的關係。"
  },
