    "question": "P.81 電壓在某些角度向下凹、也可能在換向後回彈，與整流器輸入線電流的斜率有何關係？",
    "takeaway": "共用電感上的電壓取決於 di/dt；快速正斜率使 PCC 相對來源下降，負斜率可能相對來源抬升，實際凹痕極性仍依量測參考和共用電路決定。",
