        "理想橋整流瞬時電壓 vdraw=100−(−80)=180 V，電流由 a→D1→DC+→負載→DC−→D6→b 閉合。",
        "如果另有大 Cd 且電容端原先保持 200 V，高於此刻 180 V 的整流源尺度，這一刻理想橋不必供應新電荷，負載可由電容放電。"
