      "選定相電壓最高者給 DC+、最低者由 DC− 返回，每 60° 有一個相別的最高／最低排行發生變化，因此共有六個整流區段。每顆上橋或下橋二極體在自己相別擔任最高或最低的 120° 期間流過 Id。"
