    "assumptions": [
      "本頁嚴格限定三相平衡純正弦、DC 側連續固定 Id、無 AC 來源電感換向重疊、理想二極體，且無大電容維持 DC 高電壓。",
      "原講義 P.86 另有 Cd 與 Ls，那是一個不同負載與換流模型；P.88 的 Vd0=1.35VLL 不可宣稱為任意三相電容整流器的恆定 DC Bus。"
    ],
    "pitfall": "把線對線 VLL 誤用相電壓 VLN，或把 1.35VLL／PF≈0.955 當作任何含 Cd、Ls 或非平衡三相的共通結果。",
    "check": {
      "q": "三相 VLL=400 Vrms、Id=10 A、50 Hz 理想無重疊六脈波橋，平均 Vd0 與輸入真 PF 近似多少？",
      "a": "平均 Vd0≈540.19 V、主漣波 300 Hz、真 PF≈0.955；只限理想連續 Id 且無 DC 濾波保持模型。"
    },
    "tryIt": "對照 P.88 六脈波整流電壓和三相 ±Id/0 線電流，先算六段平均，再核對 0.816／0.780／0.955 的來源。"
