        "tex": "i_a=i_u,\\quad i_c=I_d-i_u",
        "plain": "新上橋電流 ia=iu；舊上橋電流 ic=Id−iu",
        "why": "DC 側固定 Id、上橋兩相共同導流並保持其餘下橋導通的單次重疊模型。"
