    "94": {
      "lesson": "bus",
      "title": "三相大電容整流：THD、DPF 與真 PF 為何會隨負載改變？",
      "question": "P.94 圖 5-37 上 DPF 仍接近 1，真 PF 卻可能不到 0.8，這與電流諧波和負載有什麼關係？",
      "takeaway": "真功率因數 PF 同時包含基波相位 DPF 和諧波畸變。電容充電脈衝即使基波接近同相，仍可能因 THDi 很高而使真 PF 明顯下降；曲線只屬圖 5-36 的指定模型。",
      "intuition": [
        "圖 5-37 的橫軸是 Id/Ishort circuit 的正規化負載電流，不是所有整流器可共用的負載百分比。負載增加會改變二極體充電窗口、來源電感電流，因此 THD、基波相位角和 PF 都會一起變。",
        "曲線中 DPF 是電流基波相對電壓基波的 cosφ1；THDi 是扣除基波後其他電流諧波相對基波的 RMS；PF 是實功與總伏安比。DPF 接近 1 不保證整流器輸入電流像正弦。"
      ],
      "steps": [
        {
          "title": "先判斷圖 5-36 的工作域",
          "detail": "來源三相平衡正弦、每相有 Ls、DC 電壓視為大電容保持，負載決定充電脈衝；與 P.89 固定直流電流且瞬間換向的 120° 電流模型不同。"
        },
        {
          "title": "用傅立葉拆開輸入相電流",
          "detail": "定義 Is1 為相線電流基波 RMS，Ish 是其餘諧波 RMS；總 Irms 的平方等於各正交諧波 RMS 平方和，因而 THDi 不需要把相位角混進去。"
        },
        {
          "title": "分別計算位移因數與失真因數",
          "detail": "若供電電壓為純正弦且電流沒有 DC 分量，實功只來自同頻基波，PF=cosφ1×Is1/Is=DPF/√(1+THDi²)。"
        },
        {
          "title": "最後核對負載曲線方向而非照抄數字",
          "detail": "原圖的較輕負載區充電較集中、THD 高，PF 較低；隨負載增加，導通窗口改變使 THD 下降、PF 改善，但不是普遍單調的實機保證。"
        }
      ],
      "equations": [
        {
          "label": "輸入相線電流總 RMS",
          "tex": "I_{s,\\rm rms}^2=I_{s1,\\rm rms}^2+\\sum_{h\\ne 1}I_{sh,\\rm rms}^2",
          "plain": "總相電流 RMS²=基波 RMS²+所有非基波諧波 RMS²",
          "why": "取完整週期、正交傅立葉諧波；應排除或另處理非穩態、DC 分量與非整數週取樣影響。"
        },
        {
          "label": "電流總諧波失真",
          "tex": "THD_i=\\frac{\\sqrt{I_s^2-I_{s1}^2}}{I_{s1}}",
          "plain": "THDi=非基波諧波 RMS/基波 RMS",
          "why": "僅基波 RMS 非零且電流有可定義的穩態週期；百分比表示時另乘 100%。"
        },
        {
          "label": "純正弦電壓下的功率因數分解",
          "tex": "PF=\\frac{DPF}{\\sqrt{1+THD_i^2}},\\quad DPF=\\cos\\phi_1",
          "plain": "PF=DPF/√(1+THDi²)，DPF=cos(電壓與電流基波相位差)",
          "why": "必須來源電壓純正弦、電流無 DC 分量；電網已有顯著電壓諧波時不能直接用此簡式。"
        }
      ],
      "worked": {
        "given": "以一個獨立理想正弦來源例子核對關係：相線基波 RMS 10 A、其他諧波合成 RMS 6 A，基波與電壓位移因數 DPF=0.98。",
        "steps": [
          "總電流 RMS=√(10²+6²)=√136≈11.662 A；THDi=6/10=0.60=60%。",
          "失真因數 Is1/Is=10/11.662≈0.8575，即使基波幾乎同相，波形仍有明顯諧波。",
          "真 PF=0.98×10/11.662≈0.8404，不等於 DPF=0.98。此例用於核對公式，不是從圖 5-37 擬合出的原始資料。"
        ],
        "result": "圖 5-37 將 THD、DPF、PF 畫在同一橫軸，是比較指定來源 Ls 與固定 Vd 模型的負載效應；不能把示意數值當任何三相橋都適用的測試規範。"
      },
      "assumptions": [
        "圖 5-37 的負載軸為原來源模型的 Id/Ishort circuit，圖中趨勢不能直接換算成輸出瓦數、元件額定或固定 DC Id 的六脈波結論。",
        "純正弦電源是 PF 分解成 DPF×失真因數的必要假設；若來源電壓已有諧波或三相不平衡，應用週期功率及各相 RMS 重新量測。"
      ],
      "pitfall": "將 DPF≈1 誤判成 PF≈1、忽略電流諧波；或將 P.94 的 THD 下降曲線直接套到無來源 Ls 的方波整流器。",
      "check": {
        "q": "當 THDi=60%、DPF=0.98 且來源電壓純正弦時，輸入真 PF 約多少？",
        "a": "PF=0.98/√(1+0.60²)≈0.8404；位移角小不代表畸變電流很小。"
      },
      "tryIt": "在圖 5-37 以同一負載位置分別讀 DPF、THD、PF，再用 PF=DPF/√(1+THDi²) 做一致性檢查；勿把橫軸當安培值。"
    },
